import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Base premiums per item type (parallel price-list catalogue) ---
  it.todo("quotes an empty item list -- premium 5 G (processing fee only)");
  it.todo("quotes a single sword -- base premium 100 G, premium 115 G (100 + 10 first insurance + 5 fee)");
  it.todo("quotes a single amulet -- base premium 60 G, premium 71 G (60 + 6 first insurance + 5 fee)");
  it.todo("quotes a single staff -- base premium 80 G, premium 93 G (80 + 8 first insurance + 5 fee)");
  it.todo("quotes a single potion -- base premium 40 G, premium 49 G (40 + 4 first insurance + 5 fee)");
  it.todo("quotes a single rune -- base premium 25 G, premium 33 G (25 + 2.5 first insurance + 5 fee, rounded up)");
  it.todo("quotes a single moonstone -- base premium 25 G, premium 33 G (component price list applies to moonstone too)");

  // --- Component building block of 3 alike components ---
  it.todo("quotes 2 runes -- base premium 50 G (no block)");
  it.todo("quotes 3 runes -- base premium 60 G (block applies)");
  it.todo("quotes 4 runes -- base premium 100 G (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes -- base premium 175 G (no block at 7)");
  it.todo("quotes 2 runes + 1 moonstone -- base premium 75 G (no block: alike means same type)");
  it.todo("quotes 3 runes + 3 moonstones -- base premium 120 G (two separate blocks, one per type)");

  // --- Item-specific modifiers ---
  it.todo("quotes a cursed sword -- 50 % curse surcharge on the item base premium (100 -> 150)");
  it.todo("quotes a sword with enchantment 5 -- 30 % high-enchantment surcharge applies at the threshold (100 -> 130)");
  it.todo("quotes a sword with enchantment 4 -- no high-enchantment surcharge (100 -> 100)");
  it.todo("quotes a cursed sword with enchantment 5 -- both item surcharges apply (100 + 50 + 30 = 180)");
  it.todo("quotes a cursed sword and a plain amulet -- item surcharge applies only to the cursed item: 160 base + 50 curse = 210 before policy modifiers and fee");

  // --- Policy-wide modifiers ---
  it.todo("quotes for a customer with exactly 2 years -- 20 % loyalty discount applies on the policy base premium");
  it.todo("quotes for a customer with 1 year -- no loyalty discount");
  it.todo("applies the 10 % first-insurance surcharge on the policy base premium of every quote");
  it.todo("applies a 15 % follow-up discount on the customer's second quote and no follow-up discount on the first");
  it.todo("applies the 15 % follow-up discount to the third quote as well (each contract after the first)");
  it.todo("adds the 5 G processing fee at the very end, after all percentage modifiers");

  // --- Premium rounding ---
  it.todo("rounds a premium of 197.5 G up to 198 G (in the MHPCO's favor)");
  it.todo("rounds only the final premium, keeping intermediate amounts as fractions");

  // --- Premium integration examples ---
  it.todo("newcomer (0 years, first contract) with a cursed steel sword enchantment 3 -- premium 165 G");
  it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 -- premium 160 G");

  // --- Quote rejection ---
  it.todo("rejects a quote containing an unknown item type (e.g. broomstick) -- throws an Error (observable contract: CLI exits non-zero, error on stderr, no results on stdout)");

  // --- Insurance sum and cap ---
  it.todo("reports cap 2000 G for a policy covering one sword (2 x insurance sum 1000 G)");
  it.todo("reports cap 3200 G for a policy covering a sword and an amulet (insurance sum 1600 G)");
  it.todo("reports cap 4000 G for a policy covering two swords (insurance sum 2000 G)");
  it.todo("reports cap 3500 G for a policy covering a sword and 3 runes -- insurance sum 1750 G (block discount does not reduce the insurance sum)");
  it.todo("reports cap 2000 G for a cursed sword -- premium modifiers do not raise the cap (unmodified insurance value)");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("claims 500 G damage on a regular steel sword enchantment 3 -- payout 400 G (full reimbursement minus 100 G deductible)");
  it.todo("claims 200 G damage on a rune (no enchantment, no material) -- payout 100 G (no special clause applies)");
  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G -- payout 600 G");

  // --- Claim: special clauses ---
  it.todo("claims 1000 G damage on a steel sword enchantment 9 -- payout 400 G (50 % high-enchantment clause first, then deductible)");
  it.todo("claims 1000 G damage on a dragon-material sword enchantment 8 -- payout 400 G (high-enchantment clause at the threshold, then deductible)");
  it.todo("claims 800 G damage on a dragon-material sword enchantment 5 -- payout 700 G (dragon clause only: full reimbursement, then deductible)");
  it.todo("claims 1000 G damage on a dragon-material sword enchantment 9 -- payout 400 G (50 % rule wins over dragon material, then deductible)");

  // --- Claim: multiple items of the same type ---
  it.todo("claims two sword damages against a policy covering two swords -- each damage entry gets its own deductible");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) -- throws an Error (CLI exits non-zero)");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("first claim of 1500 G against a sword policy -- payout 1400 G, remainingCap 600 G");
  it.todo("second successive claim of 1500 G against the same policy -- payout 600 G, remainingCap 0 G (desired payout reduced to remaining cap)");

  // --- Payout rounding ---
  it.todo("rounds a payout of 350.5 G down to 350 G (in the MHPCO's favor)");

  // --- Claim rejection ---
  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured) -- throws an Error (CLI exits non-zero)");
  it.todo("rejects a claim whose damage entry has an unknown item type -- throws an Error (CLI exits non-zero)");
  it.todo("rejects a claim with a negative damage amount (-200) -- throws an Error (CLI exits non-zero)");

  // --- Scenario runner: sequential steps, results aligned to steps ---
  it.todo("runs a scenario and returns results in the same length and order as the input steps");
  it.todo("resolves a claim step's policy field as the zero-based index of the quote step that created the policy");

  // --- CLI adapter ---
  it.todo("CLI reads a scenario from stdin and writes {results: [...]} JSON to stdout with exit code 0");
  it.todo("CLI exits with a non-zero status code and writes an error description to stderr, writing no results to stdout, for an unknown item type in a quote");
  it.todo("CLI exits with a non-zero status code and writes an error description to stderr for an invalid claim");
});

